            require_once dirname(__DIR__) . '/app/PilotHttp/ObjectListView.php';
            $prefix=(string)getenv('FMONITOR_PROCESS_TABLE_PREFIX');$legacy=(string)getenv('FMONITOR_LEGACY_TABLE_PREFIX');
            if(preg_match('/^[A-Za-z0-9_]+$/D',$prefix)!==1||preg_match('/^[A-Za-z0-9_]+$/D',$legacy)!==1)throw new RuntimeException();
            $db=new mysqli(getenv('FMONITOR_DB_HOST')?:'127.0.0.1',(string)getenv('FMONITOR_DB_USER'),(string)getenv('FMONITOR_DB_PASSWORD'),(string)getenv('FMONITOR_DB_NAME'),(int)(getenv('FMONITOR_DB_PORT')?:3306));$db->set_charset('utf8mb4');
            $email=(string)($_SERVER['REMOTE_USER']??'');$userQuery=$db->prepare("SELECT user_id,full_name,email FROM `{$prefix}fm2_pilot_users` WHERE LOWER(email)=LOWER(?) AND status=1 LIMIT 2");$userQuery->bind_param('s',$email);$userQuery->execute();$users=$userQuery->get_result()->fetch_all(MYSQLI_ASSOC);if(count($users)!==1)throw new RuntimeException();$row=$users[0];$permissions=\FMonitor2\PilotHttp\AccessPolicy::forUser($db,$prefix,(int)$row['user_id']);if(!\FMonitor2\PilotHttp\AccessPolicy::grants($permissions,\FMonitor2\PilotHttp\AccessPolicy::OBJECTS_READ))self::respond(403,"Access denied.\n",'text/plain; charset=UTF-8');$user=new \FMonitor2\PilotHttp\HttpUser((int)$row['user_id'],(string)$row['full_name'],(string)$row['email'],$permissions);
            [$objects,$filters]=self::readObjects($db,$prefix,$legacy);
            $caps=[];foreach(['assignment_order.prepare','assignment_order.confirm_registration','installation.open']as$cap)$caps[$cap]=$user->can($cap);$allowed=['Требуется распоряжение'=>$caps['assignment_order.prepare'],'Распоряжение подготовлено'=>$caps['assignment_order.confirm_registration'],'Готов к открытию'=>$caps['installation.open']];
