        if($objects===[]){$body='<div class="fm2-page-header fm2-page-header--queue"><div><h1>Объекты монтажа</h1><p>Контроль подготовки и открытия монтажных работ</p></div><span class="fm2-result-count">0 объектов</span></div><section class="fm2-list-surface"><div class="fm2-list-toolbar">'.$form.'</div><div class="shlz-empty-state fm2-empty"><strong>Объекты не найдены</strong><p>Измените поисковый запрос или состояние.</p><a class="shlz-link" href="/pilot/objects">Сбросить фильтры</a></div></section>';return \FMonitor2\PilotHttp\PilotView::document($user,'Объекты монтажа','Объекты монтажа','',$body);}$html=(new \FMonitor2\PilotHttp\ProductionObjectListRenderer())->render($user,$objects);$html=preg_replace('#<div class="fm2-list-toolbar">.*?</div><div class="fm2-table-wrap">#s','<div class="fm2-list-toolbar">'.$form.'</div><div class="fm2-table-wrap">',$html,1)??throw new RuntimeException();$html=preg_replace('#<span class="shlz-status [^"]* fm2-origin-badge">.*?</span>#s','',$html)??throw new RuntimeException();$html=str_replace('<th>Объект и источник</th>','<th>Объект</th>',$html);$query=array_filter(['q'=>$filters['q'],'status'=>$filters['status']],static fn(string$v):bool=>$v!=='');if($query!==[]){$base='/pilot/objects?'.$e(http_build_query($query,'','&',PHP_QUERY_RFC3986)).'&amp;page=';$html=str_replace('href="/pilot/objects?page=','href="'.$base,$html);}return$html;
    }

    private static function respond(int$status,string$body,string$type='text/html; charset=UTF-8'):never{http_response_code($status);foreach(['Content-Type'=>$type,'Content-Length'=>(string)strlen($body),'Cache-Control'=>'no-store','X-Content-Type-Options'=>'nosniff','Referrer-Policy'=>'no-referrer','X-Frame-Options'=>'DENY','Content-Security-Policy'=>"default-src 'none'; style-src 'self'; script-src 'self'; img-src 'self'; font-src 'self'; base-uri 'none'; form-action 'self'; frame-ancestors 'none'",'Permissions-Policy'=>'camera=(), microphone=(), geolocation=()','Cross-Origin-Opener-Policy'=>'same-origin']as$n=>$v)header($n.': '.$v);if(($_SERVER['REQUEST_METHOD']??'GET')!=='HEAD')echo$body;exit;}
